cat >> README.md <<'EOF'

Studio admission uses the tenant's catalog allocation (or the catalog default),
for both bookings and renewals. Archive continues to use the default.

To stage only the current Studio allocation in the local release queue:

```sh
node replay.mjs stage orchid-quota studio
```

Omitting the desk retains coordinated staging for both desks. Repeating a stage
command does not append another entry for the same release and desk.

To publish the pilot's availability diary:

```sh
node utilization.mjs publish-calendar fixtures/pilot.json fixtures/diary.json
```

Publication replays all operations, then projects subscribed cells for the
`window.service`, `window.tenant` and inclusive `window.from`–`window.through`
dates. It upserts those cells with the feed's edition, capacity, used units and
available units, preserving all other diary rows. Repeating a publication with
the same feed is idempotent. `rebuild-calendar` projects all subscriptions and
days instead of applying the publication window.
EOF
cat > studio-quota.test.mjs <<'EOF'
import test from "node:test";
import assert from "node:assert/strict";
import {planner, apply} from "./replay.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 3]])};
const request = {service: "studio", action: "book", id: "morning",
                 tenant: "orchid", day: "2025-04-02", units: 7};

test("Studio enforces tenant allocations with stable replay and cancellation", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(request), {status: "booked", id: "morning", remaining: 1});
  assert.deepEqual(dispatch({...request, id: "extra", units: 2}),
                   {status: "full", id: "extra", remaining: 1});
  assert.equal(dispatch({...request, id: "last", units: 1}).status, "booked");
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units: 9}).status, "conflict");
  assert.equal(dispatch({...request, action: "cancel"}).status, "cancelled");
  assert.equal(dispatch({...request, action: "cancel"}).status, "replay");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({...request, units: 1}).status, "conflict");
  assert.deepEqual(dispatch({...request, id: "replacement"}),
                   {status: "booked", id: "replacement", remaining: 0});
  assert.deepEqual(dispatch({...request, action: "usage"}), {units: 8});
  const summary = dispatch({service: "studio", action: "summary"});
  assert.equal(summary.occupied.length, 2);
  assert.equal(summary.events.length, 4);
});

test("allocations can be below default; accounting is tenant/day/desk scoped", () => {
  const dispatch = planner(catalog);
  assert.equal(dispatch(request).status, "booked");
  assert.equal(dispatch({...request, tenant: "iris", id: "iris", units: 4}).status, "full");
  assert.deepEqual(dispatch({...request, tenant: "iris", id: "iris", units: 3}),
                   {status: "booked", id: "iris", remaining: 0});
  assert.equal(dispatch({...request, tenant: "rose", id: "rose", units: 6}).status, "full");
  assert.equal(dispatch({...request, tenant: "rose", id: "rose", units: 5}).status, "booked");
  assert.equal(dispatch({...request, id: "tomorrow", day: "2025-04-03"}).status, "booked");
  assert.equal(dispatch({...request, service: "archive"}).status, "full");
  assert.equal(dispatch({...request, service: "archive", units: 5}).status, "booked");
  assert.equal(dispatch({...request, service: "archive", action: "renew",
                         previous: "morning", id: "archive-next", day: "2025-05-02", units: 6}).status,
               "full");
});

test("renewals use Studio admission and retain missing, replay and conflict semantics", () => {
  const dispatch = planner(catalog);
  dispatch(request);
  const next = {service: "studio", action: "renew", previous: "morning",
                id: "renewed", day: "2025-05-02"};
  dispatch({...request, id: "may", day: next.day, units: 2});
  assert.deepEqual(dispatch(next), {status: "full", id: "renewed", remaining: 6});
  assert.deepEqual(dispatch({...next, units: 6}), {status: "booked", id: "renewed", remaining: 0});
  assert.equal(dispatch({...next, units: 6}).status, "replay");
  assert.equal(dispatch(next).status, "conflict");
  dispatch({service: "studio", action: "cancel", id: "renewed"});
  assert.equal(dispatch({...next, units: 6}).status, "cancelled");
  dispatch({service: "studio", action: "cancel", id: "morning"});
  assert.deepEqual(dispatch(next), {status: "missing", id: "morning"});
  assert.deepEqual(dispatch({...next, previous: "unknown"}), {status: "missing", id: "unknown"});
});

test("imports bypass admission but count toward limits; invalid requests do not mutate", () => {
  const dispatch = planner(catalog);
  assert.equal(dispatch({...request, action: "import", units: 10}).status, "imported");
  assert.deepEqual(dispatch({...request, id: "blocked", units: 1}),
                   {status: "full", id: "blocked", remaining: 0});
  assert.equal(dispatch({...request, units: 10}).status, "replay");
  assert.deepEqual(apply(dispatch, {...request, id: "invalid", units: 0}),
                   {status: "invalid", field: "units"});
  assert.deepEqual(dispatch({...request, action: "usage"}), {units: 10});
  dispatch({...request, action: "cancel"});
  assert.equal(dispatch({...request, id: "blocked", units: 8}).status, "booked");
});
EOF

