    const diary = join(dir, "diary.json");
    const original = JSON.parse(readFileSync("fixtures/diary.json", "utf8"));
    const untouched = original.filter(row => !(row.service === "studio" && row.tenant === "orchid" &&
      row.day >= feed.window.from && row.day <= feed.window.through));
    writeFileSync(source, JSON.stringify(feed));
    writeFileSync(diary, JSON.stringify([...untouched, {...expected[0], edition: "old", cap: 5, used: 0}]));
    const args = [resolve("utilization.mjs"), "publish-calendar", source, diary];
